// ignore_for_file: document_ignores, lines_longer_than_80_chars

import 'package:equatable/equatable.dart';

/// Detailed validated skin analysis report generated by the Skin Analyst AI agent.
class SkinReport extends Equatable {
  /// Creates a [SkinReport].
  const SkinReport({
    required this.headline,
    required this.summary,
    required this.overall,
    required this.profileChips,
    required this.strengths,
    required this.regions,
    required this.routinePreview,
    required this.coachMessage,
    required this.disclaimers,
    required this.safety,
    this.goalValidation,
  });

  /// Catchy, empathetic, and empowering headline (8-80 chars).
  final String headline;

  /// Short introductory summary (20-280 chars).
  final String summary;

  /// Overall composite score, qualitative band, and supportive caption.
  final OverallScore overall;

  /// Horizontal header profile tags/chips (e.g. skin type, goal, focus).
  final List<ProfileChip> profileChips;

  /// Natural skin strengths and celebrated resilience indicators.
  final List<StrengthItem> strengths;

  /// Anatomical focus areas and dermatological observations.
  final List<RegionItem> regions;

  /// Optional alignment validation of the user's primary goal.
  final GoalValidation? goalValidation;

  /// Recommended morning and night skincare routine steps.
  final List<RoutineStep> routinePreview;

  /// Warm, encouraging guidance message from the AI skin coach.
  final String coachMessage;

  /// Legal and non-diagnostic wellness disclaimers.
  final List<String> disclaimers;

  /// Safety evaluation flags and professional review alerts.
  final SafetyReport safety;

  @override
  List<Object?> get props => [
    headline,
    summary,
    overall,
    profileChips,
    strengths,
    regions,
    goalValidation,
    routinePreview,
    coachMessage,
    disclaimers,
    safety,
  ];
}

/// Overall skin score and qualitative band indicator.
class OverallScore extends Equatable {
  /// Creates an [OverallScore].
  const OverallScore({
    required this.score,
    required this.band,
    required this.caption,
  });

  /// Honest raw overall score (0.0 to 100.0).
  final double score;

  /// Qualitative band: 'strength' | 'good' | 'moderate' | 'watch' | 'focus'.
  final String band;

  /// Gentle, non-punitive caption.
  final String caption;

  @override
  List<Object?> get props => [score, band, caption];
}

/// Profile chip tag displayed at the top of the report.
class ProfileChip extends Equatable {
  /// Creates a [ProfileChip].
  const ProfileChip({
    required this.label,
    required this.sublabel,
    required this.kind,
  });

  /// Chip title (e.g. 'Combination', 'Moisture').
  final String label;

  /// Chip category/role (e.g. 'Skin type', 'Focus · your goal').
  final String sublabel;

  /// Semantic chip kind: 'skin_type' | 'concern' | 'goal' | 'sensitivity'.
  final String kind;

  @override
  List<Object?> get props => [label, sublabel, kind];
}

/// Celebrated skin strength item.
class StrengthItem extends Equatable {
  /// Creates a [StrengthItem].
  const StrengthItem({
    required this.title,
    required this.description,
    required this.evidence,
  });

  /// Empowering title (e.g. 'Clear Complexion', 'Firm Foundation').
  final String title;

  /// Narrative explanation of this skin strength.
  final String description;

  /// Source measurement evidence points.
  final List<Evidence> evidence;

  @override
  List<Object?> get props => [title, description, evidence];
}

/// Regional anatomical focus block.
class RegionItem extends Equatable {
  /// Creates a [RegionItem].
  const RegionItem({
    required this.area,
    required this.title,
    required this.observation,
    required this.whyItMatters,
    required this.suggestedFocus,
    required this.confidence,
    required this.evidence,
  });

  /// Anatomical zone: 'eye_area' | 'whole_face' | 'forehead' | 'cheeks' | 'chin' | 'nose'.
  final String area;

  /// Section title (e.g. 'Eye area', 'Skin balance').
  final String title;

  /// What was measured.
  final String observation;

  /// Pedagogical educational explanation.
  final String whyItMatters;

  /// Actionable topical skincare focus.
  final String suggestedFocus;

  /// Confidence level: 'measured' | 'zone_measured'.
  final String confidence;

  /// Measurement evidence data.
  final List<Evidence> evidence;

  @override
  List<Object?> get props => [
    area,
    title,
    observation,
    whyItMatters,
    suggestedFocus,
    confidence,
    evidence,
  ];
}

/// Source measurement evidence item.
class Evidence extends Equatable {
  /// Creates an [Evidence].
  const Evidence({required this.concern, required this.raw});

  /// Canonical concern identifier (e.g. 'droopy_upper_eyelid', 'moisture').
  final String concern;

  /// Raw algorithm score.
  final double raw;

  @override
  List<Object?> get props => [concern, raw];
}

/// Alignment evaluation of the user's personal skincare goal.
class GoalValidation extends Equatable {
  /// Creates a [GoalValidation].
  const GoalValidation({
    required this.goal,
    required this.alignment,
    required this.value,
    required this.explanation,
  });

  /// Name of the user's primary goal (e.g. 'moisture', 'radiance').
  final String goal;

  /// Alignment level: 'strong' | 'partial' | 'weak' | 'not_measurable'.
  final String alignment;

  /// Degree of coherence (0.0 to 1.0).
  final double value;

  /// Empathetic explanation for the user.
  final String explanation;

  @override
  List<Object?> get props => [goal, alignment, value, explanation];
}

/// Individual step within the personalized routine preview.
class RoutineStep extends Equatable {
  /// Creates a [RoutineStep].
  const RoutineStep({
    required this.step,
    required this.name,
    required this.timeOfDay,
    required this.ingredientIds,
    required this.instruction,
    required this.why,
  });

  /// Sequence index (1 to 6).
  final int step;

  /// Product or step title (e.g. 'Gentle Hydrating Cleanser').
  final String name;

  /// When to apply: 'am' | 'pm' | 'both'.
  final String timeOfDay;

  /// Highlighted active ingredient identifiers.
  final List<String> ingredientIds;

  /// Application guidelines.
  final String instruction;

  /// Why this step is recommended for their skin profile.
  final String why;

  @override
  List<Object?> get props => [
    step,
    name,
    timeOfDay,
    ingredientIds,
    instruction,
    why,
  ];
}

/// Safety assessment flags and professional dermatologist referral reasons.
class SafetyReport extends Equatable {
  /// Creates a [SafetyReport].
  const SafetyReport({
    required this.needsProfessionalReview,
    this.reasons = const [],
  });

  /// Whether an in-person dermatological consult is recommended.
  final bool needsProfessionalReview;

  /// Reasons triggering the professional review alert.
  final List<String> reasons;

  @override
  List<Object?> get props => [needsProfessionalReview, reasons];
}
